#![cfg_attr(not(test), allow(dead_code))]
#![forbid(unsafe_code)]

//! Feature-private native geometry generated by the host ELF adapter. The
//! decoder understands owned regions and source spans, never ELF or auxv.
use super::mapping_plan::{mapping_budget, mapping_request, reserved_request};
use super::owned_source::sealed_source_reader;
use super::owned_source_plan::{self, launch_input, owned_source_image, source_span};
use super::paging::page_permissions;
use crate::task::{executable_interval, executable_interval_set};

pub(super) const encoded_size: usize = 592;
pub(super) const source_limit: u64 = 512 * 1024;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum plan_error {
    header,
    source,
    region,
    stack,
    executable,
    admission,
}

pub(super) struct native_plan {
    pub source_length: u64,
    pub source_fnv64: u64,
    pub entry: u64,
    pub stack_pointer: u64,
    pub regions: [mapping_request; 9],
    pub reservations: [reserved_request; 3],
    pub spans: [source_span; 9],
    pub executable: executable_interval_set,
    pub reported_main_entry: u64,
    pub reported_main_phdr: u64,
    pub reported_interpreter_bias: u64,
    pub reported_break: u64,
}

impl native_plan {
    pub(super) fn decode(bytes: &[u8]) -> Result<Self, plan_error> {
        if bytes.len() != encoded_size {
            return Err(plan_error::header);
        }
        let word =
            |index: usize| u64::from_le_bytes(bytes[index * 8..index * 8 + 8].try_into().unwrap());
        if &bytes[..8] != b"ANLEPLN1"
            || word(1) != 1
            || [word(6), word(7), word(8), word(9)] != [9, 9, 2, 8]
        {
            return Err(plan_error::header);
        }
        if !(1..=source_limit).contains(&word(2)) {
            return Err(plan_error::source);
        }
        let mut regions = [mapping_request {
            virtual_address: 0,
            page_count: 0,
            permissions: page_permissions {
                user: true,
                writable: false,
                executable: false,
            },
        }; 9];
        let mut total_pages = 0u64;
        for (index, region) in regions.iter_mut().enumerate() {
            let start = 16 + index * 3;
            let flags = word(start + 2);
            if !matches!(flags, 1 | 3 | 5) || word(start + 1) == 0 {
                return Err(plan_error::region);
            }
            *region = mapping_request {
                virtual_address: word(start),
                page_count: word(start + 1),
                permissions: page_permissions {
                    user: true,
                    writable: flags & 2 != 0,
                    executable: flags & 4 != 0,
                },
            };
            total_pages = total_pages
                .checked_add(region.page_count)
                .ok_or(plan_error::region)?;
        }
        if total_pages > 128 {
            return Err(plan_error::region);
        }
        let stack_start = word(10);
        let stack_end = word(11);
        if stack_start < 4096
            || stack_start & 4095 != 0
            || stack_start.checked_add(65536) != Some(stack_end)
            || regions[8].virtual_address != stack_start
            || regions[8].page_count != 16
            || !regions[8].permissions.writable
            || regions[8].permissions.executable
            || word(5) & 15 != 0
        {
            return Err(plan_error::stack);
        }
        let reservations = [
            reserved_request {
                virtual_address: 0,
                page_count: 512,
            },
            reserved_request {
                virtual_address: stack_start - 4096,
                page_count: 1,
            },
            reserved_request {
                virtual_address: stack_end,
                page_count: 1,
            },
        ];
        let spans = core::array::from_fn(|index| {
            let start = 43 + index * 3;
            source_span {
                destination: word(start),
                source_offset: word(start + 1),
                length: word(start + 2),
            }
        });
        let intervals = [
            executable_interval {
                start: word(70),
                end: word(71),
            },
            executable_interval {
                start: word(72),
                end: word(73),
            },
        ];
        let executable =
            executable_interval_set::new(&intervals).map_err(|_| plan_error::executable)?;
        let result = Self {
            source_length: word(2),
            source_fnv64: word(3),
            entry: word(4),
            stack_pointer: word(5),
            regions,
            reservations,
            spans,
            executable,
            reported_main_entry: word(12),
            reported_main_phdr: word(13),
            reported_interpreter_bias: word(14),
            reported_break: word(15),
        };
        owned_source_plan::validate_input(&result.input(), result.source_length)
            .map_err(|_| plan_error::admission)?;
        Ok(result)
    }

    pub(super) fn input(&self) -> launch_input<'_> {
        launch_input {
            regions: &self.regions,
            reservations: &self.reservations,
            budget: mapping_budget {
                data_pages: 128,
                table_frames: 32,
            },
            spans: &self.spans,
            executable: self.executable,
            entry: self.entry,
            stack_region: 8,
            stack_pointer: self.stack_pointer,
        }
    }

    pub(super) fn image<'a>(
        &'a self,
        reader: sealed_source_reader<'a>,
    ) -> Result<owned_source_image<'a>, plan_error> {
        if reader.length() != self.source_length {
            return Err(plan_error::source);
        }
        owned_source_image::new(self.input(), reader).map_err(|_| plan_error::admission)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn encoded() -> [u8; encoded_size] {
        let mut words = [0u64; 74];
        let stack = 0x7fff00000000;
        words[..16].copy_from_slice(&[
            u64::from_le_bytes(*b"ANLEPLN1"),
            1,
            88 * 4096,
            1,
            0x60001000,
            stack + 65536 - 16,
            9,
            9,
            2,
            8,
            stack,
            stack + 65536,
            0x40002000,
            0x40000040,
            0x60000000,
            0x40009000,
        ]);
        let geometry = [
            (0x40000000, 2, 1),
            (0x40002000, 4, 5),
            (0x40006000, 1, 1),
            (0x40007000, 2, 3),
            (0x60000000, 1, 1),
            (0x60001000, 47, 5),
            (0x60030000, 11, 1),
            (0x6003b000, 4, 3),
            (stack, 16, 3),
        ];
        let mut offset = 0;
        for (index, (address, pages, flags)) in geometry.into_iter().enumerate() {
            words[16 + index * 3..19 + index * 3].copy_from_slice(&[address, pages, flags]);
            words[43 + index * 3..46 + index * 3].copy_from_slice(&[address, offset, pages * 4096]);
            offset += pages * 4096;
        }
        words[70..].copy_from_slice(&[0x40002000, 0x40003000, 0x60001000, 0x60002000]);
        let mut bytes = [0; encoded_size];
        for (destination, word) in bytes.chunks_exact_mut(8).zip(words) {
            destination.copy_from_slice(&word.to_le_bytes());
        }
        bytes
    }

    fn changed(index: usize, value: u64) -> [u8; encoded_size] {
        let mut bytes = encoded();
        bytes[index * 8..index * 8 + 8].copy_from_slice(&value.to_le_bytes());
        bytes
    }

    #[test]
    fn admits_native_geometry_without_source_authority() {
        let plan = native_plan::decode(&encoded()).unwrap();
        assert_eq!(plan.entry, 0x60001000);
        assert_eq!(plan.regions.iter().map(|r| r.page_count).sum::<u64>(), 88);
        assert!(!plan.executable.contains(0x50000000));
    }

    #[test]
    fn rejects_header_and_source_boundaries() {
        for (index, value) in [
            (0, 0),
            (1, 2),
            (2, 0),
            (2, source_limit + 1),
            (6, 8),
            (7, 10),
            (8, 3),
            (9, 7),
        ] {
            assert!(native_plan::decode(&changed(index, value)).is_err());
        }
        assert!(native_plan::decode(&encoded()[..encoded_size - 1]).is_err());
    }

    #[test]
    fn rejects_write_execute_and_region_budget_overflow() {
        for (index, value) in [
            (18, 7),
            (18, 0),
            (17, 129),
            (17, u64::MAX),
            (16, u64::MAX - 4095),
        ] {
            assert!(native_plan::decode(&changed(index, value)).is_err());
        }
    }

    #[test]
    fn rejects_source_escape_overlap_and_uninitialized_entry() {
        for (index, value) in [
            (44, u64::MAX),
            (45, u64::MAX),
            (46, 0x40000000),
            (4, 0x60002000),
            (48, 1),
        ] {
            assert!(
                native_plan::decode(&changed(index, value)).is_err(),
                "word {index}"
            );
        }
    }

    #[test]
    fn rejects_stack_slack_and_bad_executable_membership() {
        for (index, value) in [
            (5, 0x7fff00010001),
            (5, 0x7fff00000000),
            (10, 0),
            (11, u64::MAX),
            (70, 0x50000000),
            (71, 0x60001001),
        ] {
            assert!(
                native_plan::decode(&changed(index, value)).is_err(),
                "word {index}"
            );
        }
    }
}
